def backfill_metadata():
    db = op.get_bind()
    payload = sa.JSON().with_variant(postgresql.JSONB(), 'postgresql')
    paper = sa.table('papers', sa.column('id', sa.String()), sa.column('metadata_json', payload))
    authors = sa.table('authors', sa.column('id', sa.String()), sa.column('display_name', sa.Text()))
    credit = sa.table('paper_authors', sa.column('paper_id', sa.String()), sa.column('position', sa.Integer()),
                      sa.column('author_id', sa.String()))
    for item in db.execute(sa.select(paper)).mappings():
        names = (item['metadata_json'] or {}).get('authors') or []
        for index, name in enumerate(names[:500], 1):
            if isinstance(name, str) and name.strip():
                author_id = str(uuid4())
                db.execute(authors.insert().values(id=author_id, display_name=name))
                db.execute(credit.insert().values(paper_id=item['id'], position=index, author_id=author_id))
    document = sa.table('document_versions', sa.column('id', sa.String()), sa.column('provenance', payload),
                        sa.column('licence_url', sa.String()))
    for item in db.execute(sa.select(document).where(document.c.provenance.is_not(None))).mappings():
        licence = (item['provenance'] or {}).get('licence')
        if isinstance(licence, str) and 0 < len(licence) <= 512:
            db.execute(sa.text("INSERT INTO licences (url) VALUES (:url) ON CONFLICT (url) DO NOTHING"), {"url": licence})
            db.execute(document.update().where(document.c.id == item['id']).values(licence_url=licence))


